+            old_hc_size,
+            old_n_eclasses,
+            self.memo.len(),
+            self.number_of_classes(),
+            n_unions,
+            trimmed_nodes,
+        );
+
+        debug_assert!(self.check_memo());
+        self.clean = true;
+        n_unions
