+use super::*;
+
+// Class ids are drawn from a dense sequence, but most can cease to be roots.
+// Keep live records adjacent for iteration and index them directly by root id.
+#[derive(Clone, Debug)]
+pub(super) struct ClassStore<L, D> {
+    entries: Vec<(Id, EClass<L, D>)>,
+}
+
+impl<L, D> Default for ClassStore<L, D> {
+    fn default() -> Self {
+        Self {
+            entries: Vec::new(),
+        }
+    }
+}
+
+impl<L, D> ClassStore<L, D> {
+    pub(super) fn values(&self) -> impl ExactSizeIterator<Item = &EClass<L, D>> {
+        self.entries.iter().map(|(_, class)| class)
+    }
+
+    pub(super) fn values_mut(&mut self) -> impl ExactSizeIterator<Item = &mut EClass<L, D>> {
+        self.entries.iter_mut().map(|(_, class)| class)
+    }
+
+    pub(super) fn records_mut(&mut self) -> &mut [(Id, EClass<L, D>)] {
+        &mut self.entries
+    }
+
+    pub(super) fn len(&self) -> usize {
+        self.entries.len()
+    }
+
+    #[inline]
+    pub(super) fn at(&self, pos: usize) -> &EClass<L, D> {
+        &self.entries[pos].1
+    }
+
+    #[inline]
+    pub(super) fn at_mut(&mut self, pos: usize) -> &mut EClass<L, D> {
+        &mut self.entries[pos].1
+    }
+
+    pub(super) fn insert(&mut self, id: Id, class: EClass<L, D>) {
+        self.entries.push((id, class));
+    }
+
+    pub(super) fn remove(
+        &mut self,
+        pos: usize,
+        representatives: &mut Representatives,
+    ) -> EClass<L, D> {
+        let (_, removed) = self.entries.swap_remove(pos);
+        if let Some((moved, _)) = self.entries.get(pos) {
+            representatives.locate(*moved, pos);
+        }
+        removed
+    }
+
+    // Expand recently derived witnesses first when recording proofs. For
+    // ordinary matching, process the smaller terms first so that child
+    // equalities are available when their parents are instantiated.
+    pub(super) fn order(
+        &mut self,
+        representatives: &mut Representatives,
+        sizes: &[usize],
+        proving: bool,
+    ) {
+        if proving {
+            self.entries.sort_unstable_by_key(|(id, _)| core::cmp::Reverse(*id));
+        } else {
+            self.entries.sort_unstable_by_key(|(id, _)| {
+                let n = usize::from(*id);
+                (sizes[n], !n)
+            });
+        }
+        for (pos, (id, _)) in self.entries.iter().enumerate() {
+            representatives.locate(*id, pos);
+        }
+    }
+
+    // The proof engine consumes a class map. Lend it the records without a
+    // Clone bound on analysis data, restoring their order even on unwind.
+    pub(super) fn with_map<R>(&mut self, f: impl FnOnce(&HashMap<Id, EClass<L, D>>) -> R) -> R {
+        struct Loan<'a, L, D> {
+            entries: &'a mut Vec<(Id, EClass<L, D>)>,
+            order: Vec<Id>,
+            map: HashMap<Id, EClass<L, D>>,
+        }
+        impl<L, D> Drop for Loan<'_, L, D> {
+            fn drop(&mut self) {
+                for &id in &self.order {
+                    #[allow(deprecated)]
+                    let class = self.map.remove(&id).unwrap();
+                    self.entries.push((id, class));
+                }
+            }
+        }
+        let order = self.entries.iter().map(|(id, _)| *id).collect();
+        let map = self.entries.drain(..).collect();
+        let loan = Loan {
+            entries: &mut self.entries,
+            order,
+            map,
+        };
+        f(&loan.map)
+    }
+}
+
+impl<L, D> IntoIterator for ClassStore<L, D> {
+    type Item = (Id, EClass<L, D>);
+    type IntoIter = alloc::vec::IntoIter<Self::Item>;
+    fn into_iter(self) -> Self::IntoIter {
+        self.entries.into_iter()
+    }
+}
+
+impl<L, D> FromIterator<(Id, EClass<L, D>)> for ClassStore<L, D> {
+    fn from_iter<I: IntoIterator<Item = (Id, EClass<L, D>)>>(iter: I) -> Self {
+        Self {
+            entries: iter.into_iter().collect(),
+        }
+    }
+}
+
+#[cfg(feature = "serde-1")]
+impl<L: Serialize, D: Serialize> Serialize for ClassStore<L, D> {
+    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
+        s.collect_map(self.entries.iter().map(|(id, class)| (id, class)))
+    }
+}
+
+#[cfg(feature = "serde-1")]
+impl<'de, L: Deserialize<'de>, D: Deserialize<'de>> Deserialize<'de> for ClassStore<L, D> {
+    fn deserialize<S: serde::Deserializer<'de>>(s: S) -> Result<Self, S::Error> {
+        let mut store: Self = HashMap::<Id, EClass<L, D>>::deserialize(s)?
+            .into_iter()
+            .collect();
+        store.entries.sort_unstable_by_key(|(id, _)| *id);
+        Ok(store)
+    }
+}
