+use super::*;
+
+// Extract a minimum-size term using the same live class positions as rebuild.
+// Queue entries and costs can both be looked up without hashing class ids.
+pub(super) fn smallest<L: Language, N: Analysis<L>>(
+    eg: &EGraph<L, N>,
+    root: Id,
+) -> (usize, RecExpr<L>) {
+    let len = eg.classes.len();
+    let mut best = vec![None::<(usize, usize)>; len];
+    let mut queued = vec![true; len];
+    let mut work: VecDeque<_> = (0..len).collect();
+    while let Some(pos) = work.pop_front() {
+        queued[pos] = false;
+        let class = eg.classes.at(pos);
+        assert!(!class.nodes.is_empty(), "Can't extract, eclass is empty: {class:?}");
+        let old = best[pos];
+        if matches!(old, Some((1, _))) {
+            continue;
+        }
+        let mut choice = old;
+        for (i, node) in class.nodes.iter().enumerate() {
+            let cost = node.children().iter().try_fold(1usize, |sum, &id| {
+                Some(sum.saturating_add(best[eg.unionfind.position(id)]?.0))
+            });
+            if let Some(cost) = cost
+                && choice.is_none_or(|(prior, _)| cost < prior)
+            {
+                choice = Some((cost, i));
+                if cost == 1 {
+                    break;
+                }
+            }
+        }
+        if choice != old {
+            best[pos] = choice;
+            for id in class.parents() {
+                let parent = eg.unionfind.position(id);
+                if !core::mem::replace(&mut queued[parent], true) {
+                    work.push_back(parent);
+                }
+            }
+        }
+    }
+    for (pos, choice) in best.iter().enumerate() {
+        if choice.is_none() {
+            let class = eg.classes.at(pos);
+            log::warn!("Failed to compute cost for eclass {}: {:?}", class.id, class.nodes);
+        }
+    }
+    let node = |id| {
+        let pos = eg.unionfind.position(id);
+        eg.classes.at(pos).nodes[best[pos].unwrap().1].clone()
+    };
+    let cost = best[eg.unionfind.position(root)].unwrap().0;
+    (cost, node(root).build_recexpr(node))
+}
