+            .find_entry(stored.hash, |p| *p == id)
+            .unwrap()
+            .remove();
+        let key = stored.node.map_children(|c| if c == from { to } else { c });
+        let other = self.intern(key, id);
+        (other != id).then_some(other)
+    }
+
+    pub(super) fn len(&self) -> usize {
+        self.table.len()
+    }
+
+    pub(super) fn is_empty(&self) -> bool {
+        self.table.is_empty()
+    }
+
+    pub(super) fn into_nodes(self) -> impl Iterator<Item = (L, Id)> {
+        self.keys
+            .into_iter()
+            .enumerate()
+            .filter_map(|(i, key)| Some((key?.node, i.into())))
+    }
+}
+
+impl<L: Language> FromIterator<(L, Id)> for Memo<L> {
+    fn from_iter<I: IntoIterator<Item = (L, Id)>>(iter: I) -> Self {
+        let mut result = Self::default();
+        for (node, id) in iter {
+            // Older serialized graphs can include several previous keys for an id.
+            if result.keys.get(usize::from(id)).is_none_or(Option::is_none) {
+                result.intern(node, id);
+            }
+        }
+        result
+    }
+}
+
+#[cfg(feature = "serde-1")]
+impl<L: Serialize> Serialize for Memo<L> {
+    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
+        use serde::ser::SerializeSeq;
+        let mut seq = s.serialize_seq(Some(self.table.len()))?;
+        for (i, key) in self.keys.iter().enumerate() {
+            if let Some(key) = key {
+                seq.serialize_element(&(&key.node, Id::from(i)))?;
+            }
+        }
+        seq.end()
+    }
+}
+
+#[cfg(feature = "serde-1")]
+impl<'de, L: Language + Deserialize<'de>> Deserialize<'de> for Memo<L> {
+    fn deserialize<S: serde::Deserializer<'de>>(s: S) -> Result<Self, S::Error> {
+        Ok(Vec::<(L, Id)>::deserialize(s)?.into_iter().collect())
+    }
+}
+
+// The on-disk worklist contains enode ids. Saving the displaced owners
+// lets previous readers repair them by ordinary lookup. On load, the
+// first rebuild reconstructs current keys and all outstanding collisions.
+#[cfg(feature = "serde-1")]
+pub(super) mod pending {
+    use super::*;
+
+    pub(crate) fn serialize<S: serde::Serializer>(
+        pairs: &VecDeque<(Id, Id)>,
+        s: S,
+    ) -> Result<S::Ok, S::Error> {
+        s.collect_seq(pairs.iter().map(|(_, displaced)| displaced))
+    }
+
+    pub(crate) fn deserialize<'de, D: serde::Deserializer<'de>>(
+        d: D,
+    ) -> Result<VecDeque<(Id, Id)>, D::Error> {
+        Vec::<Id>::deserialize(d)?;
+        Ok(VecDeque::new())
+    }
+}
