+use super::*;
+
+// Keep representatives flat. Members of each class form a circular list,
+// so a merge only has to visit members of the losing class.
+#[derive(Clone, Debug, Default)]
+pub(super) struct Representatives {
+    roots: Vec<Id>,
+    slots: Vec<u32>,
+    next: Vec<Id>,
+    sizes: Vec<usize>,
+    pub(super) unions: usize,
+}
+
+impl Representatives {
+    pub(super) fn make_set(&mut self) -> Id {
+        let id = Id::from(self.roots.len());
+        self.roots.push(id);
+        self.slots.push(u32::MAX);
+        self.next.push(id);
+        self.sizes.push(1);
+        id
+    }
+
+    #[inline]
+    pub(super) fn find(&self, id: Id) -> Id {
+        self.roots[usize::from(id)]
+    }
+
+    #[inline]
+    pub(super) fn position(&self, id: Id) -> usize {
+        let pos = self.slots[usize::from(id)];
+        if pos != u32::MAX {
+            pos as usize
+        } else {
+            self.slots[usize::from(self.find(id))] as usize
+        }
+    }
+
+    pub(super) fn locate(&mut self, id: Id, pos: usize) {
+        self.slots[usize::from(id)] = pos as u32;
+    }
+
+    pub(super) fn size_of(&self, id: Id) -> usize {
+        self.sizes[usize::from(id)]
+    }
+
+    pub(super) fn union(&mut self, to: Id, from: Id) {
+        self.slots[usize::from(from)] = u32::MAX;
+        self.unions += 1;
+        let mut member = from;
+        loop {
+            self.roots[usize::from(member)] = to;
+            member = self.next[usize::from(member)];
+            if member == from {
+                break;
+            }
+        }
+        self.next.swap(usize::from(to), usize::from(from));
+        self.sizes[usize::from(to)] += self.sizes[usize::from(from)];
+    }
+
+    pub(super) fn as_forest(&self) -> UnionFind {
+        let mut forest = UnionFind::default();
+        for &root in &self.roots {
+            let id = forest.make_set();
+            forest.union(root, id);
+        }
+        forest
+    }
+}
+
+#[cfg(feature = "serde-1")]
+impl Serialize for Representatives {
+    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
+        self.as_forest().serialize(s)
+    }
+}
+
+#[cfg(feature = "serde-1")]
+impl<'de> Deserialize<'de> for Representatives {
+    fn deserialize<S: serde::Deserializer<'de>>(s: S) -> Result<Self, S::Error> {
+        let mut forest = UnionFind::deserialize(s)?;
+        let mut result = Self::default();
+        for _ in 0..forest.size() {
+            result.make_set();
+        }
+        let mut pos = 0;
+        for i in 0..forest.size() {
+            let id = Id::from(i);
+            let root = forest.find_mut(id);
+            if root == id {
+                result.locate(id, pos);
+                pos += 1;
+            } else {
+                result.union(root, id);
+            }
+        }
+        Ok(result)
+    }
+}
